// ─── File: src/test/java/com/bank/whileloop/WhileNotIfTest.java ───
package com.bank.whileloop;

import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.assertj.core.api.Assertions.*;

class WhileNotIfTest {

    // ═══ CORRECT: while loop — safe against stolen conditions ═══
    @Test
    void whileLoop_safeAgainstStolenConditions() throws InterruptedException {
        Object lock = new Object();
        Queue<String> queue = new LinkedList<>();
        List<String> consumed = new CopyOnWriteArrayList<>();
        int consumers = 5;
        CountDownLatch allStarted = new CountDownLatch(consumers);
        CountDownLatch allDone = new CountDownLatch(consumers);

        // 5 consumers — all waiting for items
        for (int i = 0; i < consumers; i++) {
            new Thread(() -> {
                synchronized (lock) {
                    allStarted.countDown();
                    try {
                        while (queue.isEmpty()) {  // WHILE — re-check!
                            lock.wait(2000);
                        }
                        consumed.add(queue.poll());
                    } catch (InterruptedException e) { }
                }
                allDone.countDown();
            }).start();
        }

        allStarted.await();
        Thread.sleep(100);

        // Add only 2 items but wake ALL 5 consumers
        synchronized (lock) {
            queue.add("TRD-001");
            queue.add("TRD-002");
            lock.notifyAll();  // wakes all 5!
        }

        allDone.await(5, TimeUnit.SECONDS);

        // Only 2 consumers got items (while loop sent others back to wait)
        assertThat(consumed).hasSize(2);
        assertThat(consumed).containsExactlyInAnyOrder("TRD-001", "TRD-002");
    }

    // ═══ WRONG: if — would cause NPE on empty poll ═══
    @Test
    void ifStatement_wouldCauseNPE_demonstration() throws InterruptedException {
        Object lock = new Object();
        Queue<String> queue = new LinkedList<>();
        AtomicInteger nullPolls = new AtomicInteger(0);
        int consumers = 5;
        CountDownLatch allStarted = new CountDownLatch(consumers);
        CountDownLatch allDone = new CountDownLatch(consumers);

        // 5 consumers using IF (wrong!)
        for (int i = 0; i < consumers; i++) {
            new Thread(() -> {
                synchronized (lock) {
                    allStarted.countDown();
                    try {
                        if (queue.isEmpty()) {  // IF — only checks ONCE!
                            lock.wait(2000);
                        }
                        String item = queue.poll();
                        if (item == null) nullPolls.incrementAndGet();  // STOLEN!
                    } catch (InterruptedException e) { }
                }
                allDone.countDown();
            }).start();
        }

        allStarted.await();
        Thread.sleep(100);

        // Add 1 item, wake all 5
        synchronized (lock) {
            queue.add("TRD-001");
            lock.notifyAll();
        }

        allDone.await(5, TimeUnit.SECONDS);
        // 4 consumers got null — condition stolen! (would be NPE in real code)
        assertThat(nullPolls.get()).isGreaterThanOrEqualTo(3);
    }

    // ═══ Pattern: producer-consumer with while loop ═══
    @Test
    void correctPattern_producerConsumer() throws InterruptedException {
        Object lock = new Object();
        Queue<String> queue = new LinkedList<>();
        List<String> results = new CopyOnWriteArrayList<>();
        CountDownLatch done = new CountDownLatch(3);

        // 3 consumers with while loop
        for (int i = 0; i < 3; i++) {
            new Thread(() -> {
                synchronized (lock) {
                    try {
                        while (queue.isEmpty()) lock.wait(3000);
                        String item = queue.poll();
                        if (item != null) results.add(item);
                    } catch (InterruptedException e) { }
                }
                done.countDown();
            }).start();
        }

        Thread.sleep(100);

        // Produce 3 items one at a time
        for (int i = 0; i < 3; i++) {
            synchronized (lock) {
                queue.add("TRD-" + i);
                lock.notify();  // wake ONE consumer
            }
            Thread.sleep(50);
        }

        done.await(5, TimeUnit.SECONDS);
        assertThat(results).hasSize(3);
    }
}
